package org.formasaloido;
import java.util.*;

/** Small bounded JSON codec for the optional vision transport, without platform libraries. */
public final class Json {
 private final String input;private int at;
 private Json(String s){if(s.length()>1048576)throw new IllegalArgumentException("Respuesta demasiado grande");input=s;}
 public static Object parse(String s){Json p=new Json(s);Object v=p.value(0);p.space();if(p.at!=s.length())throw new IllegalArgumentException("Datos adicionales");return v;}
 private void space(){while(at<input.length()&&Character.isWhitespace(input.charAt(at)))at++;}
 private char take(){if(at>=input.length())throw new IllegalArgumentException("JSON incompleto");return input.charAt(at++);}
 private Object value(int depth){if(depth>32)throw new IllegalArgumentException("JSON demasiado anidado");space();char c=take();if(c=='"')return string();if(c=='{'||c=='['){boolean object=c=='{';Map<String,Object> map=new LinkedHashMap<>();List<Object> list=new ArrayList<>();space();if(at<input.length()&&input.charAt(at)==(object?'}':']')){at++;return object?map:list;}while(true){if(object){space();if(take()!='"')throw new IllegalArgumentException("Clave JSON");String key=string();space();if(take()!=':')throw new IllegalArgumentException("Separador JSON");if(map.containsKey(key))throw new IllegalArgumentException("Clave repetida");map.put(key,value(depth+1));}else list.add(value(depth+1));space();char end=take();if(end==(object?'}':']'))return object?map:list;if(end!=',')throw new IllegalArgumentException("Separador JSON");}}
  at--;int start=at;while(at<input.length()&&",]} \t\r\n".indexOf(input.charAt(at))<0)at++;String token=input.substring(start,at);if(token.equals("null"))return null;if(token.equals("true"))return true;if(token.equals("false"))return false;if(!token.matches("-?(0|[1-9][0-9]*)(\\.[0-9]+)?([eE][+-]?[0-9]+)?"))throw new IllegalArgumentException("Valor JSON");double n=Double.parseDouble(token);if(!Double.isFinite(n))throw new IllegalArgumentException("Número no finito");return n;
 }
 private String string(){StringBuilder b=new StringBuilder();while(true){char c=take();if(c=='"')return b.toString();if(c<32)throw new IllegalArgumentException("Control en texto");if(c=='\\'){c=take();switch(c){case '"':case '\\':case '/':break;case 'b':c='\b';break;case 'f':c='\f';break;case 'n':c='\n';break;case 'r':c='\r';break;case 't':c='\t';break;case 'u':if(at+4>input.length())throw new IllegalArgumentException("Escape incompleto");c=(char)Integer.parseInt(input.substring(at,at+4),16);at+=4;break;default:throw new IllegalArgumentException("Escape no válido");}}b.append(c);}}
 public static String write(Object v){if(v==null)return "null";if(v instanceof String){StringBuilder b=new StringBuilder("\"");for(char c:((String)v).toCharArray()){if(c=='"'||c=='\\')b.append('\\').append(c);else if(c<32)b.append(String.format(Locale.ROOT,"\\u%04x",(int)c));else b.append(c);}return b.append('"').toString();}if(v instanceof Number){if(!Double.isFinite(((Number)v).doubleValue()))throw new IllegalArgumentException("Número no finito");return v.toString();}if(v instanceof Boolean)return v.toString();if(v instanceof Map){List<String> out=new ArrayList<>();for(Object item:((Map<?,?>)v).entrySet()){Map.Entry<?,?> e=(Map.Entry<?,?>)item;out.add(write(e.getKey().toString())+":"+write(e.getValue()));}return "{"+String.join(",",out)+"}";}if(v instanceof Iterable){List<String> out=new ArrayList<>();for(Object item:(Iterable<?>)v)out.add(write(item));return "["+String.join(",",out)+"]";}throw new IllegalArgumentException("Tipo JSON");}
 public static Map<String,Object> object(Object... fields){Map<String,Object> out=new LinkedHashMap<>();for(int i=0;i<fields.length;i+=2)out.put(fields[i].toString(),fields[i+1]);return out;}
}
